package com.cena.restaurant
import android.app.*;import android.content.Intent;import android.net.Uri;import android.os.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.net.*;import java.util.concurrent.Executors
class MainActivity:Activity(){private val bg=Color.rgb(250,246,243);private val wine=Color.rgb(93,16,10);private val ex=Executors.newSingleThreadExecutor();private lateinit var body:LinearLayout;private val pref by lazy{getSharedPreferences("merchant",0)};private var rid="";private var rname="";private var rtimezone="America/Los_Angeles";private var curb=false;private var awaitingStripeReturn=false
 override fun onCreate(b:Bundle?){super.onCreate(b);window.statusBarColor=bg;window.navigationBarColor=bg;window.decorView.systemUiVisibility=View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR;awaitingStripeReturn=isStripeReturn(intent.data);if(pref.getString("token",null)!=null)loadRestaurants()else login()}
 override fun onResume(){super.onResume();if(awaitingStripeReturn&&rid.isNotBlank()){awaitingStripeReturn=false;paymentSetup()}}
 override fun onNewIntent(intent:Intent){super.onNewIntent(intent);setIntent(intent);if(isStripeReturn(intent.data)){awaitingStripeReturn=true;if(rid.isNotBlank()){awaitingStripeReturn=false;paymentSetup()}else if(pref.getString("token",null)!=null)loadRestaurants()}}
 private fun isStripeReturn(uri:Uri?):Boolean=uri?.scheme=="cena-restaurant"&&uri.host=="connect"&&uri.path=="/return"
 private fun base(){val sc=ScrollView(this);val outer=LinearLayout(this).apply{orientation=1;gravity=Gravity.CENTER_HORIZONTAL;setBackgroundColor(bg)};body=LinearLayout(this).apply{orientation=1;setPadding(22,22,22,24);setBackgroundColor(bg);layoutParams=LinearLayout.LayoutParams(-1,-2).apply{width=resources.displayMetrics.widthPixels.coerceAtMost((680*resources.displayMetrics.density).toInt())}};outer.addView(body);sc.addView(outer);setContentView(sc)};private fun title(s:String,z:Float=25f){body.addView(TextView(this).apply{text=s;textSize=z;setTextColor(wine);setPadding(0,8,0,8);typeface=android.graphics.Typeface.DEFAULT_BOLD})};private fun text(s:String){body.addView(TextView(this).apply{text=s;textSize=15f;setTextColor(Color.DKGRAY);setPadding(0,5,0,10)})};private fun button(s:String,f:()->Unit){body.addView(Button(this).apply{text=s;setTextColor(-1);background=GradientDrawable().apply{setColor(wine);cornerRadius=(16f+((390f-resources.displayMetrics.widthPixels/resources.displayMetrics.density)/110f*10f)).coerceIn(16f,26f)*resources.displayMetrics.density};setOnClickListener{f()}})};private fun field(s:String):EditText{val e=EditText(this).apply{hint=s};body.addView(e);return e}
 private fun go(task:()->String,done:(String)->Unit){ex.execute{try{val x=task();runOnUiThread{done(x)}}catch(e:Exception){runOnUiThread{Toast.makeText(this,e.message?:"Request failed",Toast.LENGTH_LONG).show()}}}};private fun req(path:String,method:String="GET",data:JSONObject?=null):String{val c=URL(BuildConfig.SUPABASE_URL.trimEnd('/')+path).openConnection() as HttpURLConnection;c.requestMethod=method;c.connectTimeout=9000;c.readTimeout=12000;c.setRequestProperty("apikey",BuildConfig.SUPABASE_KEY);c.setRequestProperty("Authorization","Bearer "+(pref.getString("token",BuildConfig.SUPABASE_KEY)?:BuildConfig.SUPABASE_KEY));c.setRequestProperty("Content-Type","application/json");if(data!=null){c.doOutput=true;c.outputStream.use{it.write(data.toString().toByteArray())}};val st=if(c.responseCode<400)c.inputStream else c.errorStream;val out=st.bufferedReader().readText();if(c.responseCode>=400)throw Exception(out);return out}
private fun apiReq(path:String,method:String="GET",data:JSONObject?=null):String{val c=URL(BuildConfig.CENA_API_URL.trimEnd('/')+path).openConnection() as HttpURLConnection;c.requestMethod=method;c.connectTimeout=8000;c.readTimeout=12000;pref.getString("token",null)?.let{c.setRequestProperty("Authorization","Bearer $it")};c.setRequestProperty("Content-Type","application/json");if(data!=null){c.doOutput=true;c.outputStream.use{it.write(data.toString().toByteArray())}};val code=c.responseCode;val stream=if(code<400)c.inputStream else c.errorStream;val result=stream.bufferedReader().readText();if(code>=400)throw Exception(result);return result}
 private fun trustedOnboardingUrl(url:String):Boolean{try{val uri=java.net.URI(url);return uri.scheme=="https"&&uri.host.equals("connect.stripe.com",true)&&uri.userInfo==null}catch(_:Exception){return false}}
 private fun paymentSetup(){go({apiReq("/v1/restaurants/$rid/payments")}){val info=JSONObject(it);val status=info.optString("status");base();title("Cena payments");when(status){"ready"->{text("Stripe is connected. New customer orders can be paid in Cena.");val fee=info.optInt("application_fee_cents",0);if(fee>0)text("Cena platform fee · $${"%.2f".format(fee/100.0)} per order.")};"pending"->{text("Stripe setup is in progress.");button("Refresh payment status"){paymentSetup()}};"not_connected"->{text("Connect your restaurant's Stripe account to accept in-app payments.");button("Set up Stripe securely"){go({apiReq("/v1/restaurants/$rid/stripe-onboarding","POST")}){val url=JSONObject(it).optString("url");if(!trustedOnboardingUrl(url)){Toast.makeText(this,"Stripe setup link could not be verified.",Toast.LENGTH_LONG).show()}else try{startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(url)))}catch(_:Exception){Toast.makeText(this,"Could not open Stripe setup.",Toast.LENGTH_LONG).show()}}}};else->text("Payment status is unavailable. Try again shortly.")};button("Back to restaurant"){dashboard()}}}
 private fun login(){base();title("Cena for Restaurants");text("Manage today's reservations and pickup service.");val e=field("Staff email");val p=field("Password");p.inputType=129;button("Sign in"){go({val s=req("/auth/v1/token?grant_type=password","POST",JSONObject().put("email",e.text.toString().trim()).put("password",p.text.toString()));JSONObject(s).getString("access_token")}){pref.edit().putString("token",it).apply();loadRestaurants()}};if(BuildConfig.SUPABASE_URL.isBlank())text("Connect Supabase by setting SUPABASE_URL and SUPABASE_KEY in gradle.properties.")}
 private fun loadRestaurants(){go({req("/rest/v1/merchant_memberships?select=restaurant:restaurants(id,name,address,curbside_enabled,timezone)")}){val a=JSONArray(it);base();title("Your restaurants");if(a.length()==0)text("No restaurant membership is connected to this account.");for(i in 0 until a.length()){val r=a.getJSONObject(i).optJSONObject("restaurant")?:continue;button("${r.optString("name")}\n${r.optString("address")}"){rid=r.optString("id");rname=r.optString("name");rtimezone=r.optString("timezone","America/Los_Angeles");curb=r.optBoolean("curbside_enabled");dashboard();if(awaitingStripeReturn){awaitingStripeReturn=false;paymentSetup()}}};button("Sign out"){pref.edit().clear().apply();login()}}}
 private fun dashboard(){base();title(rname);text("Today's pickup operations");button(if(curb)"Curbside pickup: ON" else "Curbside pickup: OFF"){go({req("/rest/v1/restaurants?id=eq.$rid","PATCH",JSONObject().put("curbside_enabled",!curb));"ok"}){curb=!curb;dashboard()}};button("Refresh orders"){orders()};button("Payment setup"){paymentSetup()};ordersInline()}
 private fun orders(){dashboard()}
 private fun pickupRange(start:String,end:String,timezone:String):String{val zone=runCatching{java.time.ZoneId.of(timezone)}.getOrDefault(java.time.ZoneId.of("America/Los_Angeles"));val day=java.time.format.DateTimeFormatter.ofPattern("EEE, MMM d",java.util.Locale.getDefault()).withZone(zone);val time=java.time.format.DateTimeFormatter.ofLocalizedTime(java.time.format.FormatStyle.SHORT).withLocale(java.util.Locale.getDefault()).withZone(zone);return "${day.format(java.time.Instant.parse(start))} · ${time.format(java.time.Instant.parse(start))}–${time.format(java.time.Instant.parse(end))}"}
 private fun ordersInline(){go({val zone=runCatching{java.time.ZoneId.of(rtimezone)}.getOrDefault(java.time.ZoneId.of("America/Los_Angeles"));val from=java.time.LocalDate.now(zone).atStartOfDay(zone).toInstant().toString();req("/rest/v1/orders?select=id,status,payment_status,pickup_mode,total_cents,subtotal_cents,created_at,pickup_starts_at,pickup_ends_at,restaurant_timezone,vehicle,items:order_items(name_snapshot,quantity)&restaurant_id=eq.$rid&or=(status.in.(placed,accepted,preparing,ready),pickup_starts_at.gte.$from)&order=pickup_starts_at.asc")}){val a=JSONArray(it);if(a.length()==0)text("No upcoming pickup orders. New reservations appear here.");for(i in 0 until a.length()){val o=a.getJSONObject(i);val id=o.optString("id");val status=o.optString("status");title("Order · ${status.replace('_',' ').uppercase()}",17f);val start=o.optString("pickup_starts_at");val end=o.optString("pickup_ends_at");val tz=o.optString("restaurant_timezone",rtimezone);val cents=o.optInt("total_cents",o.optInt("subtotal_cents"));val vehicle=o.optJSONObject("vehicle");val vehicleLabel=if(o.optString("pickup_mode")=="curbside")listOf(vehicle?.optString("color"),vehicle?.optString("make"),vehicle?.optString("model")).filter{!it.isNullOrBlank()&&it!="null"}.joinToString(" ") else "Counter pickup";text("${if(start.isNotBlank()&&end.isNotBlank())pickupRange(start,end,tz) else "Pickup time unavailable"}\n${o.optString("pickup_mode")} · $${"%.2f".format(cents/100.0)}\n$vehicleLabel");val lines=o.optJSONArray("items")?:JSONArray();for(j in 0 until lines.length()){val li=lines.getJSONObject(j);text("${li.optInt("quantity")} × ${li.optString("name_snapshot")}")};val next=when(status){"placed"->"accepted";"accepted"->"preparing";"preparing"->"ready";"ready"->"picked_up";else->""};if(next.isNotEmpty())button("Mark $next"){go({req("/rest/v1/rpc/update_order_status","POST",JSONObject().put("p_order_id",id).put("p_status",next));"ok"}){dashboard()}};if(status in listOf("placed","accepted","preparing","ready"))button("Cancel and refund"){AlertDialog.Builder(this).setTitle("Cancel and refund order?").setMessage("Cena will request a refund from Stripe. The order will only be treated as refunded when the payment service confirms it.").setNegativeButton("Keep order",null).setPositiveButton("Confirm refund"){_,_->go({apiReq("/v1/orders/$id/refund","POST",JSONObject())}){val result=JSONObject(it).optString("status");val message=when(result){"refunded"->"Order refunded.";"pending"->"Refund is processing. Check again shortly.";"failed"->"Refund failed. Contact Cena support.";else->"Refund status: $result"};Toast.makeText(this,message,Toast.LENGTH_LONG).show();dashboard()}}.show()}}}}
}